0001: fall back on a blank name

diff --git a/src/greeting.js b/src/greeting.js
index 9b34a29..947926c 100644
--- a/src/greeting.js
+++ b/src/greeting.js
@@ -1,3 +1,4 @@
 export function greet(name) {
-  return `Hello, ${name ?? "world"}!`;
+  const trimmed = typeof name === "string" ? name.trim() : "";
+  return `Hello, ${trimmed || "world"}!`;
 }
diff --git a/test/greeting.test.js b/test/greeting.test.js
index 0f2176f..23f0ab3 100644
--- a/test/greeting.test.js
+++ b/test/greeting.test.js
@@ -9,3 +9,8 @@ test("greet() says hello to the world", () => {
 test("greet(name) says hello by name", () => {
   assert.equal(greet("Ada"), "Hello, Ada!");
 });
+
+test("a blank name falls back to the world", () => {
+  assert.equal(greet(""), "Hello, world!");
+  assert.equal(greet("   "), "Hello, world!");
+});

